import hashlib
import json
import subprocess
from pathlib import Path


def digest(data):
    return hashlib.sha256(data).hexdigest()


def record(path):
    raw = path.read_bytes()
    text = raw.decode('utf-8')
    return {'sha256': digest(raw), 'lf_sha256': digest(text.replace('\r\n', '\n').encode()),
            'text': text}


out = Path('artifacts/performance/qoco-control-v109-checkpoint.json')
assert not out.exists(), 'Never overwrite a published checkpoint'
sources = [Path(p) for p in ('cpp/cuda/patches/qoco_device_control.cuh',
    'cpp/cuda/tests/qoco_device_control_probe.cu', 'scripts/gpu/prepare_qoco_device_control.py')]
evidence = sorted({p for p in Path('artifacts/performance').glob('*')
    if any(x in p.name for x in ('control-v108', 'control-v109')) and p != out})
helpers = sorted({p for p in Path('build/performance').glob('*')
    if p.suffix in ('.py', '.json') and any(x in p.name for x in ('control_v108', 'control_v109',
        'control_kernels_v108', 'control_kernels_v109', 'control-v108', 'control-v109'))})
logs = list(Path('build/performance/native-checks').glob('qoco-v10[89]-build.log'))
prepared = {}
runtimes = {}
for version in (108, 109):
    root = Path(f'/home/angus/build-qoco-gpu-device-ir-v{version}')
    manifest = json.loads((root/'source/spacepdhcg-device-control.json').read_text())
    files = {name: record(root/'source'/name) for name in manifest}
    assert all(files[name]['lf_sha256'] == sha for name, sha in manifest.items())
    prepared[str(version)] = files
    for path in (root/'final').iterdir():
        if path.is_file():
            runtimes[str(path)] = {'sha256': digest(path.read_bytes()), 'bytes': path.stat().st_size}
for path in map(Path, (
    '/home/angus/build-qoco-gpu-device-ir-v105/final/libqoco.so',
    '/home/angus/build-spacepdhcg-gtoc12-v107/final/libspacepdhcg_cuda.so',
    '/home/angus/build-spacepdhcg-gtoc12-v107/final/gtoc12_scvx_test',
    '/home/angus/build-spacepdhcg-gtoc12-v93/final/libspacepdhcg_cuda.so',
    '/home/angus/build-spacepdhcg-gpu-native/038695b/spacepdhcg_plan')):
    runtimes[str(path)] = {'sha256': digest(path.read_bytes()), 'bytes': path.stat().st_size}
data = {'source_base_commit': subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),
    'scope': 'Experimental QOCO device stopping and scalar control, not full GPU-controlled dispatch',
    'sources': {str(p): record(p) for p in sources},
    'prepared_sources': prepared,
    'runtimes': runtimes,
    'evidence': {str(p): record(p) for p in evidence},
    'helpers': {str(p): record(p) for p in helpers + logs},
    'failures_and_limits': [
        'Initial v108 kernel probe has exact dynamic_reg==1e-5 assertion; corrected v2 uses absolute tolerance 1e-20.',
        'v109 first triple benchmark only rotated modulo two; balanced rerun uses modulo three.',
        'v109 full device-IR memcheck fails CUDA999 with 218 errors; host-IR sanitizer passes only isolate new control.',
        'v109 balanced median 567.572 ms versus105 535.703 ms; no complete-run speedup claim.',
        'NaN direction branch, IPM loop, cuDSS dispatch, initial topology/setup still involve host.'],
    'initial_v108_probe_source': sources[1].read_text().replace('std::abs(s.dynamic_reg-1e-5)<1e-20','s.dynamic_reg==1e-5')}
out.write_text(json.dumps(data,indent=2)+'\n')
print(json.dumps({'checkpoint':str(out),'bytes':out.stat().st_size,'evidence':len(evidence),
    'helpers':len(helpers+logs),'runtimes':len(runtimes),'sha256':digest(out.read_bytes())},indent=2))

